import { Button, Card } from "antd";
import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
} from "../../../components";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useStateContext } from "../../../contexts/ContextProvider";
import { getLoggedInUser } from "../../../helpers/authUtils";
import useApi from "../../../hooks/useApi";
import departmentsApi from "../../../api/departmentsApi";
import dependantsApi from "../../../api/dependantsApi";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import { toast, ToastContainer } from "react-toastify";

export default function VitalsForm({selectedDependant}) {
  const dependantVitalsApi = useApi(hospitalsApi.hospitalStaffAction);
  const getDependantVitals = async () => {
    await dependantVitalsApi.request({
      action: "GetDependantVitals",
      dependant: selectedDependant.id,
    });
  };
  useEffect(() => {
    if (selectedDependant.id!== null) {
      getDependantVitals();
     
    }
  }, [selectedDependant]);
  const [dependantVitals, setdependantVitals] = useState();

  useEffect(() => {
    console.log("dependantVitalsApi.data", dependantVitalsApi.data);
    if (dependantVitalsApi.data && dependantVitalsApi.data) {
      setdependantVitals(dependantVitalsApi.data);
    }
  }, [dependantVitalsApi.data]);



  const { currentColor } = useStateContext();

  const createVitalsApi = useApi(hospitalsApi.hospitalStaffAction);

  const createVitals = async (data) => {
    await createVitalsApi.request(data);
  };

  useEffect(() => {
    if (createVitalsApi.data && createVitalsApi.data.vitals) {
      toast.success(createVitalsApi.data.response_message);
      getDependantVitals(selectedDependant.id);
    }

    if (
      createVitalsApi.data &&
      createVitalsApi.data.errors &&
      createVitalsApi.data.errors.length
    ) {
      setErrors(createVitalsApi.data.errors);
    }
    console.log("createVitalsApi.data", createVitalsApi.data);
  }, [createVitalsApi.data]);

  const formik = useFormik({
    initialValues: {
      temparature: "",
      weight: "",
      pulse: "",
      diastolic: "",
      systolic: "",
      height: "",
      oxygen_saturation: "",
    },

    validationSchema: Yup.object({
      temparature: Yup.number().required("Temparature is required"),
      pulse: Yup.number().required("Pulse is required"),
      weight: Yup.number().required("Weight is required"),
      height: Yup.number().required("Height is required"),
      diastolic: Yup.number().required("Diastolic pressure is required"),
      systolic: Yup.number().required("Systolic pressure is required"),
      oxygen_saturation: Yup.number().required("Oxygen saturation is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      const data = {
        action: "CreateVitals",
        dependant: selectedDependant.id,
        departmental_visit: "",
        temparature: values.temparature,
        pulse: values.pulse,
        respiration: values.respiration,
        oxygen_saturation: values.oxygen_saturation,
        height: values.height,
        weight: values.weight,
        diastolic: values.diastolic,
        systolic: values.systolic,
      };

      console.log("data at create vital", data);
      createVitals(data);
      console.log("VALZ", values);

      resetForm();
    },
  });

  const [errors, setErrors] = useState();

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  const [user, setUser] = useState();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);
  //Retrieve counties
  const [departments, setDepartments] = useState([]);
  const departmentssActionsApi = useApi(departmentsApi.departmentsAction);
  const getDepartments = async (user) => {
    console.log("Uzer", user);
    await departmentssActionsApi.request({
      action: "GetEntityDepartments",
      entity: user.entity_id,
    });
  };

  useEffect(() => {
    if (departmentssActionsApi.data && departmentssActionsApi.data.length) {
      setDepartments(
        departmentssActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
    console.log("counties", departments);
  }, [departmentssActionsApi.data]);

  useEffect(() => {
    if (user != null) {
      getDepartments(user);
    }
  }, [user]);
  return (
    <div className="grid grid-cols-2 md:grid-cols-12 mt-10 md:mt-1 mx-5">
      <div className="col-span-0 hidden md:block"></div>
      <div className="col-span-12 bg-gray-100 p-2 ">
        <p className="text-center text-2xl font-semibold">Vitals</p>
        <ToastContainer theme="colored" position="bottom-center" />
        {selectedDependant ? (
          <div className="grid grid-cols-2 md:grid-cols-4 bg-white">
            <div className=" border-1 border-gray-300 p-2">
              <p>Name</p>
              <p>{selectedDependant.title}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Gender</p>
              <p>{selectedDependant.gender}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Date of Birth</p>
              <p>{selectedDependant.date_of_birth}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Age</p>
              <p>{selectedDependant.age} Years</p>
            </div>
          </div>
        ) : (
          <div></div>
        )}

        {dependantVitals && dependantVitals.length ? (
          <div className="w-full  border-1 border-gray-200 shadow-sm rounded-sm px-2 m-2">
            <p className="text-1xl font-semibold text-center my-2">
              Vitals History
            </p>
            <div className="grid grid-cols-1 md:grid-cols-3 md:gap-x-3">
              {dependantVitals.map((x) => {
                return (
                  <Card
                    className="w-full md:w-72"
                    title={x.created}
                    variant="borderless"
                  >
                    {x.diastolic ? (
                      <p>
                        <span>Diastolic Pressure:</span>{" "}
                        <span>
                          {x.diastolic} <span></span>mmHg{" "}
                        </span>
                      </p>
                    ) : null}
                    {x.diastolic ? (
                      <p>
                        <span>Systolic Pressure:</span>{" "}
                        <span>
                          {x.systolic} <span></span>mmHg{" "}
                        </span>
                      </p>
                    ) : null}
                    {x.pulse ? (
                      <p>
                        <span>Pulse:</span>{" "}
                        <span>
                          {x.pulse} <span></span>beats per minute{" "}
                        </span>
                      </p>
                    ) : null}
                    {x.respiration ? (
                      <p>
                        <span>Respiration:</span>{" "}
                        <span>
                          {x.respiration} <span></span>breaths per minute{" "}
                        </span>
                      </p>
                    ) : null}
                    {x.temparature ? (
                      <p>
                        <span>Temparature:</span>{" "}
                        <span>
                          {x.temparature} <span></span>°C{" "}
                        </span>
                      </p>
                    ) : null}
                    {x.height ? (
                      <p>
                        <span>Height:</span>{" "}
                        <span>
                          {x.height} <span></span>cm{" "}
                        </span>
                      </p>
                    ) : null}

                    {x.weight ? (
                      <p>
                        <span>Weight:</span>{" "}
                        <span>
                          {x.weight} <span></span>kg{" "}
                        </span>
                      </p>
                    ) : null}
                  </Card>
                );
              })}
            </div>
          </div>
        ) : (
          <div>No vitals history</div>
        )}

        <div className="w-full  border-1 border-gray-200 shadow-sm rounded-sm px-2 my-2">
          <p className="text-1xl font-semibold text-center my-2">
            Add New Vitals
          </p>
          <CustomForm
            className="grid gap-2 grid-cols-1 md:grid-cols-2 my-5 md:w-full"
            layout="vertical"
            handleFinish={formik.handleSubmit}
          >
            <CustomFormItem
              touched={formik.touched.temparature}
              error={formik.errors.temparature}
            >
              <CustomInput
                id="temparature"
                name="temparature"
                onChange={formik.handleChange}
                placeholder="Enter temparature in °C (normally 37°C)"
                label="Enter temparature in °C (normally 37°C)"
                size="large"
                type="number"
                value={formik.values.temparature}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.pulse}
              error={formik.errors.pulse}
            >
              <CustomInput
                id="pulse"
                required={true}
                name="pulse"
                onChange={formik.handleChange}
                placeholder="Enter pulse (normaly 60-100 beats per minute)"
                label="Enter pulse (normaly 60-100 beats per minute)"
                size="large"
                type="number"
                value={formik.values.pulse}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.respiration}
              error={formik.errors.respiration}
            >
              <CustomInput
                id="respiration"
                required={true}
                name="respiration"
                onChange={formik.handleChange}
                placeholder="Enter respiration (normaly 12-20 breaths per minute)"
                label="Enter respiration (normaly 12-20 breaths per minute)"
                size="large"
                type="number"
                value={formik.values.respiration}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.diastolic}
              error={formik.errors.diastolic}
            >
              <CustomInput
                id="diastolic"
                name="diastolic"
                onChange={formik.handleChange}
                placeholder="Enter diastolic pressure in mmHg (normally below 80)"
                label="Enter diastolic pressure in mmHg (normally below 80)"
                size="large"
                type="number"
                value={formik.values.diastolic}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.systolic}
              error={formik.errors.systolic}
            >
              <CustomInput
                id="systolic"
                name="systolic"
                onChange={formik.handleChange}
                placeholder="Enter systolic pressure in mmHg (normally below 120)"
                label="Enter systolic pressure in mmHg (normally below 120)"
                size="large"
                type="number"
                value={formik.values.systolic}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.oxygen_saturation}
              error={formik.errors.oxygen_saturation}
            >
              <CustomInput
                id="oxygen_saturation"
                name="oxygen_saturation"
                onChange={formik.handleChange}
                placeholder="Enter oxygen saturation as % (normally between 95-100)"
                label="Enter oxygen saturation as % (normally between 95-100)"
                size="large"
                type="number"
                value={formik.values.oxygen_saturation}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.height}
              error={formik.errors.height}
            >
              <CustomInput
                id="height"
                name="height"
                onChange={formik.handleChange}
                placeholder="Enter height in cm"
                label="Enter height in cm"
                size="large"
                type="number"
                value={formik.values.height}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.weight}
              error={formik.errors.weight}
            >
              <CustomInput
                id="weight"
                name="weight"
                required={true}
                onChange={formik.handleChange}
                placeholder="Enter weight in kg"
                label="Enter weight in kg"
                size="large"
                type="number"
                value={formik.values.weight}
              />
            </CustomFormItem>

            <div className="flex w-full items-center mt-2 justify-center col-span-1 md:col-span-2">
              <button
                style={{
                  background: currentColor,
                  color: "white",
                  width: 123,
                  height: 50,
                }}
                onClick={formik.handleSubmit}
                className="w-36 rounded-md"
                color="primary"
                type="submit"
              >
                Submit
              </button>
            </div>
          </CustomForm>
        </div>
      </div>
      <div className="col-span-0 hidden md:block"></div>
    </div>
  );
}
