import { Button, Card, Flex, Radio, Table } from "antd";
import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useStateContext } from "../../../contexts/ContextProvider";
import { getLoggedInUser } from "../../../helpers/authUtils";
import useApi from "../../../hooks/useApi";
import departmentsApi from "../../../api/departmentsApi";
import dependantsApi from "../../../api/dependantsApi";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import { toast, ToastContainer } from "react-toastify";
import preparationsApi from "../../../api/drugs/preparationsApi";

export default function ConsultationForm({ selectedDependant }) {
  const [selectedDependantId, setselectedDependantId] = useState();
  const [selectedPreparation, setselectedPreparation] = useState();
  const [prescription, setprescription] = useState([]);

  const [searchText, setsearchText] = useState("");
  const [openPrescriptionModal, setopenPrescriptionModal] = useState(false);

  const columns = [
    {
      title: "Drug Name",
      dataIndex: "long_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Formulation",
      dataIndex: "formulation_title",
      render: (text) => <a>{text}</a>,
    },
    {
      title: "Components",
      dataIndex: "generics_string",
    },
  ];

  const [selectedDepartmentalVisitId, setselectedDepartmentalVisitId] =
    useState();

  const dependantDetailsApi = useApi(dependantsApi.dependantsAction);

  const getDependantDetails = async () => {
    await dependantDetailsApi.request({
      action: "GetDependantDetails",
      dependant_id: selectedDependantId,
    });
  };

  const dependantVitalsApi = useApi(hospitalsApi.hospitalStaffAction);
  const getDependantVitals = async () => {
    await dependantVitalsApi.request({
      action: "GetDependantVitals",
      dependant: selectedDependantId,
    });
  };

  const [dependantVitals, setdependantVitals] = useState();

  useEffect(() => {
    console.log("dependantVitalsApi.data", dependantVitalsApi.data);
    if (dependantVitalsApi.data && dependantVitalsApi.data) {
      setdependantVitals(dependantVitalsApi.data);
    }
  }, [dependantVitalsApi.data]);

  useEffect(() => {
    if (selectedDependantId !== null) {
      getDependantDetails(selectedDependantId);
      getDependantVitals(selectedDependantId);
    }
  }, [selectedDependantId]);

  const { currentColor, loggedInUser } = useStateContext();

  const createConsultationApi = useApi(hospitalsApi.hospitalStaffAction);
  const [preparations, setPreparations] = useState([]);

  const createConsultation = async (data) => {
    await createConsultationApi.request(data);
  };

  useEffect(() => {
    if (createConsultationApi.data && createConsultationApi.data.vitals) {
      toast.success(createConsultationApi.data.response_message);
      getDependantVitals(selectedDependantId);
    }

    if (
      createConsultationApi.data &&
      createConsultationApi.data.errors &&
      createConsultationApi.data.errors.length
    ) {
      setErrors(createConsultationApi.data.errors);
    }
    console.log("createConsultationApi.data", createConsultationApi.data);
  }, [createConsultationApi.data]);

  const formik = useFormik({
    initialValues: {
      complaint_duration_unit: "",
      complaint_duration_length: "",
      location: "",
      onset: "",
      course: "",
      aggravating_factors: "",
      previous_treatment: "",
      current_treatment: "",
      uses_tobacco: "",
      uses_alcohol: "",
      is_married: "",
      current_occupation: "",
      current_diagnosis: "",
      current_complaint: "",
    },

    validationSchema: Yup.object({
      uses_tobacco: Yup.object().required("Tobacco use is required"),
      uses_alcohol: Yup.object().required("Alcohol use is required"),
      current_complaint: Yup.string().required(
        "Current complaint entry is required"
      ),
      complaint_duration_unit: Yup.string().required(
        "Current complaint duration unit is required"
      ),
      complaint_duration_length: Yup.string().required(
        "Current complaint duration length is required"
      ),
      location: Yup.string().required("Location entry is required"),
      onset: Yup.string().required("Onset entry onset entry is required"),
      course: Yup.string().required(
        "Current complaint course entry is required"
      ),
      aggravating_factors: Yup.string().required(
        "Aggravating factors entry is required"
      ),
      is_married: Yup.object().required("Marital status entry is required"),
      current_diagnosis: Yup.string().required(
        "Current diagnosis entry is required"
      ),
      current_occupation: Yup.string().required(
        "Current occupation entry is required"
      ),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      const data = {
        action: "CreateConsultation",
        dependant: selectedDependant.id,
        department: user.employment_department,
        current_complaint: values.current_complaint,
        complaint_duration_unit: values.complaint_duration_unit,
        complaint_duration_length: values.complaint_duration_length,
        location: values.location,
        onset: values.onset,
        course: values.course,
        aggravating_factors: values.aggravating_factors,
        previous_treatment: values.previous_treatment,
        current_treatment: values.current_treatment,
        uses_alcohol: values.uses_alcohol,
        uses_tobacco: values.uses_tobacco,
        is_married: values.is_married.value,
        current_occupation: values.current_occupation,
        medicinal_allergies: values.medication_allergies,
        food_allergies: values.food_allergies,
        environmental__allergies: values.environmental__allergies,
        current_diagnosis: values.current_diagnosis,
        cigarettes_per_day: values.cigarettes_per_day,
        year_of_smoking: values.year_of_smoking,
      };

      console.log("data at create vital", data);
      createConsultation(data);
      console.log("VALZ", values);

      // resetForm();
    },
  });

  const [errors, setErrors] = useState();

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  const [user, setUser] = useState();

  //get client consultations history
  const [dependantConsultations, setdependantConsultations] = useState([]);

  const getdependantConsultationsApi = useApi(hospitalsApi.hospitalStaffAction);

  const getDependantConsultations = async (id) => {
    await getdependantConsultationsApi.request({
      action: "GetDependantConsultations",
      dependant: id,
    });
  };

  useEffect(() => {
    if (getdependantConsultationsApi.data) {
      if (getdependantConsultationsApi.data.length) {
        setdependantConsultations(getdependantConsultationsApi.data);
      }
    }
    console.log(
      "getdependantConsultationsApi.data",
      getdependantConsultationsApi.data
    );
  }, [getdependantConsultationsApi.data]);

  useEffect(() => {
    setUser(getLoggedInUser());
    getDependantConsultations();
  }, []);
  useEffect(() => {
    if (selectedDependant) {
      getDependantConsultations(selectedDependant.id);
    }
  }, [selectedDependant]);
  //Retrieve counties
  const [departments, setDepartments] = useState([]);
  const departmentssActionsApi = useApi(departmentsApi.departmentsAction);
  const getDepartments = async (user) => {
    console.log("Uzer", user);
    await departmentssActionsApi.request({
      action: "GetEntityDepartments",
      entity: user.entity_id,
    });
  };

  useEffect(() => {
    if (departmentssActionsApi.data && departmentssActionsApi.data.length) {
      setDepartments(
        departmentssActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
    console.log("counties", departments);
  }, [departmentssActionsApi.data]);

  useEffect(() => {
    if (user != null) {
      getDepartments(user);
    }
  }, [user]);

  const handleChange = (e) => {
    console.log("change", e.target.value);
    setsearchText(e.target.value);
  };

  const searchDrugApi = useApi(preparationsApi.preparationsAction);

  const searchDrug = async (data) => {
    setPreparations([]);
    setselectedPreparation(null);
    setopenPrescriptionModal(false);
    await searchDrugApi.request({
      action: "SearchPreparations",
      searchQuery: data,
    });
  };

  useEffect(() => {
    if (searchDrugApi.data && searchDrugApi.data.length) {
      setPreparations(searchDrugApi.data);
    }
  }, [searchDrugApi.data]);

  useEffect(() => {
    if (searchText !== "") {
      searchDrug(searchText);
    }
  }, [searchText]);

  const [selectedRowKeys, setSelectedRowKeys] = useState([]);

  const onSelectChange = (newSelectedRowKeys, selectedRow) => {
    setselectedPreparation(selectedRow[0]);
    setSelectedRowKeys(newSelectedRowKeys);
  };

  useEffect(() => {
    if (selectedPreparation) {
      setopenPrescriptionModal(true);
    }
  }, [selectedPreparation]);
  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  const hasSelected = selectedRowKeys.length > 0;
  const [loading, setLoading] = useState(false);
  const start = () => {
    setLoading(true);
    // ajax request after empty completing
    setTimeout(() => {
      setSelectedRowKeys([]);
      setLoading(false);
    }, 1000);
  };

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const handleCreateVisits = () => {
    if (selectedRowKeys && selectedRowKeys.length) {
      console.log("handleCreateVisits", selectedRowKeys);
      for (let i = 0; i < selectedRowKeys.length; i++) {
        // createVisit(selectedRowKeys[i]);
      }
    }
  };

  useEffect(() => {
    if (localStorage.getItem("departmentalPrescriptions")) {
      let allDepartmentalPrescriptions = [];
      let departmentalPrescriptions = [];
      allDepartmentalPrescriptions = JSON.parse(
        localStorage.getItem("departmentalPrescriptions")
      );

      departmentalPrescriptions = allDepartmentalPrescriptions?.filter(
        (x) =>
          x.owner === loggedInUser.user_id &&
          x.dependant_id == selectedDependant.id
      );
      setprescription(
        departmentalPrescriptions.find(
          (x) => (x.dependant_id = selectedDependant.id)
        )
      );
    }
  }, []);

  return (
    <div className="grid grid-cols-2 md:grid-cols-12 mt-10 md:mt-1 mx-5">
      <div className="col-span-0 hidden md:block"></div>
      <div className="col-span-12 bg-gray-100 p-2 w-full ">
        <p className="text-center text-2xl font-semibold">Consultation</p>
        <ToastContainer theme="colored" position="bottom-center" />

        {selectedDependant ? (
          <div className="grid grid-cols-2 md:grid-cols-4 bg-white border-2 border-gray-400 rounded-md mx-2">
            <div className=" border-1 border-gray-300 p-2">
              <p>Name</p>
              <p>{selectedDependant.title}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Gender</p>
              <p>{selectedDependant.gender}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Date of Birth</p>
              <p>{selectedDependant.date_of_birth}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Age</p>
              <p>{selectedDependant.age} Years</p>
            </div>
          </div>
        ) : (
          <div></div>
        )}

        <div className="w-full  border-1 border-gray-200 shadow-sm rounded-sm px-2 my-2">
          <p className="text-1xl font-semibold text-center my-2">
            Add New Consultation
          </p>
          <CustomForm
            layout="horizontal"
            handleFinish={formik.handleSubmit}
            className="grid grid-cols-1  gap-4  justify-center items-center w-full px-2 "
          >
            <div className="border-2 border-gray-400 rounded-md my-5 p-5">
              <p className="text-1xl font-semibold text-center my-2">
                Current Problem
              </p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                <CustomFormItem
                  touched={formik.touched.current_complaint}
                  error={formik.errors.current_complaint}
                >
                  <CustomTextArea
                    rows={2}
                    id="current_complaint"
                    name="current_complaint"
                    onChange={formik.handleChange}
                    placeholder="Enter current current_complaint"
                    label="Enter current current_complaint"
                    size="large"
                    type="text"
                    value={formik.values.current_complaint}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.location}
                  error={formik.errors.location}
                >
                  <CustomTextArea
                    rows={2}
                    id="location"
                    name="location"
                    onChange={formik.handleChange}
                    placeholder="Enter current location"
                    label="Enter current location"
                    size="large"
                    type="text"
                    value={formik.values.location}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.onset}
                  error={formik.errors.onset}
                >
                  <CustomTextArea
                    rows={2}
                    id="onset"
                    name="onset"
                    onChange={formik.handleChange}
                    placeholder="Enter complaint onset"
                    label="Enter complaint onset"
                    size="large"
                    type="text"
                    value={formik.values.onset}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.course}
                  error={formik.errors.course}
                >
                  <CustomTextArea
                    rows={2}
                    id="course"
                    name="course"
                    onChange={formik.handleChange}
                    placeholder="Enter complaint course"
                    label="Enter complaint course"
                    size="large"
                    type="text"
                    value={formik.values.course}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.aggravating_factors}
                  error={formik.errors.aggravating_factors}
                >
                  <CustomTextArea
                    rows={2}
                    id="aggravating_factors"
                    name="aggravating_factors"
                    onChange={formik.handleChange}
                    placeholder="Any aggravating factors"
                    label="Any aggravating factors"
                    size="large"
                    type="text"
                    value={formik.values.aggravating_factors}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.previous_treatment}
                  error={formik.errors.previous_treatment}
                >
                  <CustomTextArea
                    rows={2}
                    id="previous_treatment"
                    name="previous_treatment"
                    onChange={formik.handleChange}
                    placeholder="Any previous medication"
                    label="Any previous medication"
                    size="large"
                    type="text"
                    value={formik.values.previous_treatment}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.current_treatment}
                  error={formik.errors.current_treatment}
                >
                  <CustomTextArea
                    rows={2}
                    id="current_treatment"
                    name="current_treatment"
                    onChange={formik.handleChange}
                    placeholder="Any current medication"
                    label="Any current medication"
                    size="large"
                    type="text"
                    value={formik.values.current_treatment}
                  />
                </CustomFormItem>
                <CustomFormItem
                  touched={formik.touched.complaint_duration_unit}
                  error={formik.errors.complaint_duration_unit}
                >
                  <CustomSelectReactSelect
                    className="text-start"
                    name="complaint_duration_unit"
                    id="complaint_duration_unit"
                    label="Complaint duration unit"
                    size="large"
                    onChange={(value) =>
                      formik.setFieldValue(
                        "complaint_duration_unit",
                        value.value
                      )
                    }
                    value={formik.values.complaint_duration_unit}
                    placeholder="Complaint duration unit"
                    options={[
                      { label: "DAYS", value: "DAYS" },
                      { label: "WEEKS", value: "WEEKS" },
                      { label: "MONTHS", value: "MONTHS" },
                      { label: "YEARS", value: "YEARS" },
                    ]}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.complaint_duration_length}
                  error={formik.errors.complaint_duration_length}
                >
                  <CustomInput
                    id="complaint_duration_length"
                    name="complaint_duration_length"
                    onChange={formik.handleChange}
                    placeholder="Complaint duration"
                    label="Complaint duration"
                    size="large"
                    type="number"
                    value={formik.values.complaint_duration_length}
                  />
                </CustomFormItem>
                <CustomFormItem
                  touched={formik.touched.current_diagnosis}
                  error={formik.errors.current_diagnosis}
                >
                <CustomTextArea
                rows={2}
                id="current_diagnosis"
                name="current_diagnosis"
                onChange={formik.handleChange}
                placeholder="Current diagnosis"
                label="Current diagnosis"
                size="large"
                type="text"
                value={formik.values.current_diagnosis}
              />
                </CustomFormItem>
              </div>
            </div>

            <div className="border-2 border-gray-400 rounded-md my-5 p-5">
              <p className="text-1xl font-semibold text-center my-2">
                Social Profile
              </p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                <CustomFormItem
                  touched={formik.touched.uses_alcohol}
                  error={formik.errors.uses_alcohol}
                >
                  <CustomSelectReactSelect
                    className="text-start"
                    name="uses_alcohol"
                    id="uses_alcohol"
                    label="Uses alcohol"
                    size="large"
                    onChange={(value) =>
                      formik.setFieldValue("uses_alcohol", value)
                    }
                    value={formik.values.uses_alcohol}
                    placeholder="Uses alcohol"
                    options={[
                      { label: "NO", value: "NO" },
                      { label: "QUIT", value: "QUIT" },
                      { label: "YES", value: "YES" },
                    ]}
                  />
                </CustomFormItem>

                <CustomFormItem
                  touched={formik.touched.uses_tobacco}
                  error={formik.errors.uses_tobacco}
                >
                  <CustomSelectReactSelect
                    className="text-start"
                    name="uses_tobacco"
                    id="uses_tobacco"
                    label="Uses tobacco"
                    size="large"
                    onChange={(value) =>
                      formik.setFieldValue("uses_tobacco", value)
                    }
                    value={formik.values.uses_tobacco}
                    placeholder="Uses tobacco"
                    options={[
                      { label: "NO", value: "NO" },
                      { label: "QUIT", value: "QUIT" },
                      { label: "YES", value: "YES" },
                    ]}
                  />
                </CustomFormItem>

                {formik.values.uses_tobacco === "YES" && (
                  <CustomFormItem
                    touched={formik.touched.cigarettes_per_day}
                    error={formik.errors.cigarettes_per_day}
                  >
                    <CustomInput
                      id="cigarettes_per_day"
                      name="cigarettes_per_day"
                      onChange={formik.handleChange}
                      placeholder="Average cigarettes per day"
                      label="Average cigarettes per day"
                      size="large"
                      type="number"
                      value={formik.values.cigarettes_per_day}
                    />
                  </CustomFormItem>
                )}
                {formik.values.uses_tobacco === "YES" && (
                  <CustomFormItem
                    touched={formik.touched.years_of_smoking}
                    error={formik.errors.years_of_smoking}
                  >
                    <CustomInput
                      id="years_of_smoking"
                      name="years_of_smoking"
                      onChange={formik.handleChange}
                      placeholder="Years of smoking"
                      label="Years of smoking"
                      size="large"
                      type="number"
                      value={formik.values.years_of_smoking}
                    />
                  </CustomFormItem>
                )}

                <CustomFormItem
                  touched={formik.touched.is_married}
                  error={formik.errors.is_married}
                >
                  <CustomSelectReactSelect
                    className="text-start"
                    name="is_married"
                    id="is_married"
                    label="Select marital status"
                    size="large"
                    onChange={(value) =>
                      formik.setFieldValue("is_married", value)
                    }
                    value={formik.values.is_married}
                    placeholder="Select marital status"
                    options={[
                      { label: "DIVORCED", value: "DIVORCED" },
                      { label: "MARRIED", value: "MARRIED" },
                      { label: "SINGLE", value: "SINGLE" },
                      { label: "UNDERAGE", value: "UNDERAGE" },
                    ]}
                  />
                </CustomFormItem>
                <CustomFormItem
                  touched={formik.touched.current_occupation}
                  error={formik.errors.current_occupation}
                >
                  <CustomInput
                    id="current_occupation"
                    name="current_occupation"
                    onChange={formik.handleChange}
                    placeholder="Current occupation"
                    label="Current occupation"
                    size="large"
                    type="text"
                    value={formik.values.current_occupation}
                  />
                </CustomFormItem>
              </div>
            </div>

            <div className="border-2 border-gray-400 rounded-md my-5 p-5">
              <p className="text-1xl font-semibold text-center my-2">
                Allergies
              </p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                <CustomFormItem
                  touched={formik.touched.medication_allergies}
                  error={formik.errors.medication_allergies}
                >
                  <CustomTextArea
                    rows={2}
                    id="medication_allergies"
                    name="medication_allergies"
                    onChange={formik.handleChange}
                    placeholder="Any medication allergies?"
                    label="Any medication allergies?"
                    size="large"
                    type="text"
                    value={formik.values.medication_allergies}
                  />
                </CustomFormItem>
                <CustomFormItem
                  touched={formik.touched.food_allergies}
                  error={formik.errors.food_allergies}
                >
                  <CustomTextArea
                    rows={2}
                    id="food_allergies"
                    name="food_allergies"
                    onChange={formik.handleChange}
                    placeholder="Any food allergies?"
                    label="Any food allergies?"
                    size="large"
                    type="text"
                    value={formik.values.food_allergies}
                  />
                </CustomFormItem>
                <CustomFormItem
                  touched={formik.touched.environmental_allergies}
                  error={formik.errors.environmental_allergies}
                >
                  <CustomTextArea
                    rows={2}
                    id="environmental_allergies"
                    name="environmental_allergies"
                    onChange={formik.handleChange}
                    placeholder="Any environmental allergies?"
                    label="Any environmental allergies?"
                    size="large"
                    type="text"
                    value={formik.values.environmental_allergies}
                  />
                </CustomFormItem>
              </div>
            </div>

            <button
              id="formikPrescription"
              style={{ background: currentColor }}
              className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1"
              color="primary"
              type="submit"
            >
              Submit
            </button>
          </CustomForm>
        </div>
        <p>Recent Consultations</p>
        {dependantConsultations && dependantConsultations.length ? (
          <div>
            <p>
              <span>Consultations: </span>
              <span>{dependantConsultations.length}</span>
            </p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {dependantConsultations.map((consultation) => {
                return (
                  <div className="grid grid-cols-1 md:grid-cols-2 w-full gap-2 border-2 border-gray-300 shadow-md bg-white">
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Date</p>
                      <p>{consultation.created}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Department</p>
                      <p>{consultation.department_name}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Doctor</p>
                      <p>{consultation.doctor_name}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Complaint</p>
                      <p>{consultation.current_complaint}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Duration Unit</p>
                      <p>{consultation.complaint_duration_unit}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Duration Length</p>
                      <p>{consultation.complaint_duration_length}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Location</p>
                      <p>{consultation.location}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Onset</p>
                      <p>{consultation.onset}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Course</p>
                      <p>{consultation.course}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Aggravating Factors</p>
                      <p>{consultation.aggravating_factors}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Previous Treatment</p>
                      <p>{consultation.previous_treatment}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Marital Status</p>
                      <p>{consultation.is}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Drug Allergies</p>
                      <p>{consultation.medicinal_allergies}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Food Allergies</p>
                      <p>{consultation.food_allergies}</p>
                    </div>
                    <div className="flex flex-col border-1  rounded-md p-2 bg-white">
                      <p className="font-bold">Environmental Allergies</p>
                      <p>{consultation.environmental_allergies}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ) : (
          <div>
            <p>No recent consultations for this client</p>
          </div>
        )}
      </div>
      <div className="col-span-0 hidden md:block"></div>
    </div>
  );
}
